package work;

public class Work10 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int a=24;
		for(int i=1;i<=10;i++) {
			System.out.println(i+"x"+a+"="+(i*a));		
		}
		int b=50;
		int i=1;
		do {
			System.out.println(i+"x"+b+"="+(i*b));
			i++;
		}
		while(i<=10);
		   
		int c=29;
		int j=1;
		while(j<=10) {
			System.out.println(c+"x"+j+"="+(c*j));
			j++;

		}

	}

}
